import {makeChoice} from './simple-choice.js';
import {bindAmountInput,formatAmount,parseAmount} from './amount-input.js';
import {moneyParts} from './money.js';
import {financeTotals,financeSummary} from './finance-math.js';
export function initAdminOperations({form,node,getItems,openVehicle,notify}){
 const choices=[];for(const [name,list,editable]of [['condition',['Nuevo','Seminuevo','Usado'],false],['city',['Santa Cruz de la Sierra','La Paz','El Alto','Cochabamba','Sucre','Tarija','Oruro','Potosí','Trinidad','Cobija','Montero','Sacaba','Quillacollo','Riberalta'],true],['currency',null,false],['status',null,false]])choices.push(makeChoice(form.elements[name],list,{node,label:form.elements[name].closest('label').firstChild.textContent.trim(),editable}));
 const country=form.elements.country;country.value='Bolivia';country.readOnly=true;country.removeAttribute('list');country.setAttribute('aria-readonly','true');const color=form.elements.color;color.removeAttribute('list');color.placeholder='Escribe el color de esta unidad';const price=bindAmountInput(form.elements.price);form.elements.price.placeholder='Ej. 60,000';
 const theme=node('button','admin-theme-toggle');theme.type='button';theme.id='admin-theme';const header=document.querySelector('.admin-header>div');header.prepend(theme);const headerSize=()=>document.body.style.setProperty('--admin-header-height',Math.ceil(document.querySelector('.admin-header').getBoundingClientRect().height)+'px');new ResizeObserver(headerSize).observe(document.querySelector('.admin-header'));headerSize();let pref;try{pref=localStorage.getItem('torres-admin-theme');}catch{}const setTheme=light=>{document.body.classList.toggle('admin-light',light);document.documentElement.style.colorScheme=light?'light':'dark';theme.textContent=light?'☾ Modo oscuro':'☼ Modo claro';theme.setAttribute('aria-label',light?'Activar modo oscuro del administrador':'Activar modo claro del administrador');theme.setAttribute('aria-pressed',String(light));};setTheme(pref==='light');theme.onclick=()=>{const light=!document.body.classList.contains('admin-light');setTheme(light);try{localStorage.setItem('torres-admin-theme',light?'light':'dark');}catch{}};
 let privateCurrencyTouched=false;const section=node('section','private-finance');section.innerHTML='<div class="private-heading"><span class="eyebrow">SOLO PARA ADMINISTRACIÓN</span><h2>Acuerdo privado y cierre de venta</h2><p>El mínimo autorizado, los datos del propietario y tu comisión no aparecen en el catálogo ni en la ruleta.</p></div><div class="finance-fields"></div><div class="finance-approval" hidden></div><div class="finance-preview" aria-live="polite"></div><p class="finance-note">Las ganancias se registran cuando el vehículo queda Vendido y tiene un precio final. El precio anunciado no se usa como precio de cierre.</p>';
 document.querySelector('#save').before(section);const grid=section.querySelector('.finance-fields'),fields={},formats=new Map();
 const add=(key,label,type='text',options)=>{const wrapper=node('label','',label),input=node(type==='select'?'select':type==='textarea'?'textarea':'input');input.id='finance-'+key;if(input.tagName==='INPUT')input.type=type;input.setAttribute('aria-label',label);if(options)for(const [value,title]of options){const o=node('option','',title);o.value=value;input.append(o);}wrapper.append(input);grid.append(wrapper);fields[key]=input;if(type==='amount'){input.type='text';formats.set(key,bindAmountInput(input,draw));}if(type==='select')choices.push(makeChoice(input,null,{node,label}));return wrapper;};
 add('ownerName','Propietario / cliente (privado)');add('currency','Moneda del acuerdo privado','select',[['BOB','Bs · Bolivianos'],['USD','US$ · Dólares']]);add('minSalePrice','Precio mínimo de venta autorizado','amount');add('mode','Cómo se calcula tu comisión','select',[['percent','Porcentaje del precio final'],['fixed','Comisión fija pactada'],['margin','Excedente sobre el monto del propietario']]);const rate=add('rate','Comisión pactada (%)','number');fields.rate.min='0';fields.rate.max='100';fields.rate.step='0.01';const fixed=add('fixedCommission','Comisión fija pactada','amount'),target=add('ownerTarget','Monto que debe recibir el propietario','amount');add('salePrice','Precio final negociado de venta','amount');add('saleDate','Fecha de cierre','date');add('costs','Gastos a cargo de tu comisión','amount');add('received','Comisión que ya cobraste','amount');add('notes','Notas del acuerdo (privadas)','textarea');
 const approval=section.querySelector('.finance-approval'),approvalLabel=node('label','','Autorización adicional del propietario para vender bajo el mínimo');fields.belowMinimumApproval=node('textarea');fields.belowMinimumApproval.id='finance-belowMinimumApproval';fields.belowMinimumApproval.placeholder='Registra quién autorizó la rebaja y cuándo.';approvalLabel.append(fields.belowMinimumApproval);approval.append(approvalLabel);
 function capture(){return Object.fromEntries(Object.entries(fields).map(([key,input])=>[key,formats.has(key)?parseAmount(input.value):input.value]));}
 function showAmount(n,currency){return(currency==='BOB'?'Bs ':'US$ ')+Number(n||0).toLocaleString('en-US',{maximumFractionDigits:2});}
 function draw(){if(!fields.mode)return;const f=capture(),t=financeTotals(f),currency=f.currency;rate.hidden=f.mode!=='percent';fixed.hidden=f.mode!=='fixed';target.hidden=f.mode!=='margin';approval.hidden=!(f.salePrice>0&&f.minSalePrice!==null&&f.salePrice<f.minSalePrice);const preview=section.querySelector('.finance-preview');preview.replaceChildren();const money=moneyParts({price:form.elements.price.value,priceAmount:parseAmount(form.elements.price.value),currency:form.elements.currency.value});if(f.minSalePrice!==null&&money.currency===currency&&money.amount!==null){const room=money.amount-f.minSalePrice;preview.append(node('p','negotiation-room',`Margen de negociación desde el precio anunciado: ${showAmount(room,currency)}. Mínimo privado: ${showAmount(f.minSalePrice,currency)}.`));}if(t.recorded&&((f.mode==='percent'&&parseAmount(f.rate)===null)||(f.mode==='fixed'&&f.fixedCommission===null)||(f.mode==='margin'&&f.ownerTarget===null))){preview.append(node('p','finance-warning','Completa el acuerdo de comisión para calcular tu ganancia.'));return;}if(!t.recorded){preview.append(node('p','','Completa el precio final negociado para ver cuánto recibe el propietario y cuánto ganas.'));return;}preview.append(node('strong','',form.elements.status.value==='sold'?'Cierre registrado al guardar':'Simulación del cierre · aún no suma a tus ventas'));const cards=node('div','finance-result-grid');for(const [title,value]of [['Precio de cierre',t.sale],['Para el propietario',t.ownerPayout],['Comisión bruta',t.gross],['Comisión neta tras gastos',t.net],['Ya cobrado',t.received],['Comisión por cobrar',t.pending]]){const card=node('div');card.append(node('small','',title),node('strong',value<0?'loss':'',showAmount(value,currency)));cards.append(card);}preview.append(cards);if(t.belowMinimum)preview.append(node('p','finance-warning','El cierre está por debajo del mínimo: registra la autorización adicional antes de guardar.'));if(t.net<0)preview.append(node('p','finance-warning','Este cierre genera una pérdida neta con los gastos registrados.'));}
 fields.currency.addEventListener('change',()=>{privateCurrencyTouched=true;});form.elements.currency.addEventListener('change',()=>{if(!privateCurrencyTouched&&['minSalePrice','ownerTarget','fixedCommission','salePrice','costs','received'].every(k=>parseAmount(fields[k].value)===null)){fields.currency.value=form.elements.currency.value||'BOB';choices.forEach(c=>c.sync());draw();}});section.addEventListener('input',draw);section.addEventListener('change',draw);for(const input of [form.elements.price,form.elements.currency,form.elements.status]){input.addEventListener('input',draw);input.addEventListener('change',draw);} 
 const report=node('section','finance-dashboard');report.id='finance-dashboard';report.innerHTML='<div class="finance-report-heading"><div><span class="eyebrow">TUS RESULTADOS, EN PRIVADO</span><h2>Ventas y comisiones</h2><p>Se calculan con el precio final negociado. Bs y dólares se mantienen separados.</p></div></div><div class="finance-summary"></div><details><summary>Ver cierres por vehículo</summary><div class="finance-report-rows"></div></details>';document.querySelector('.inventory-tools').before(report);
 function renderReport(vehicles){const summary=report.querySelector('.finance-summary');summary.replaceChildren();for(const group of financeSummary(vehicles)){const box=node('div','finance-currency-card');box.append(node('h3','',`${group.currency==='BOB'?'Bolivianos · Bs':'Dólares · US$'} · ${group.count} cierres`));for(const [label,key]of [['Comisión bruta generada','gross'],['Gastos','costs'],['Ganancia neta generada','net'],['Comisión cobrada','received'],['Comisión pendiente de cobro','pending']]){const row=node('div');row.append(node('span','',label),node('strong',group[key]<0?'loss':'',showAmount(group[key],group.currency)));box.append(row);}summary.append(box);}const rows=report.querySelector('.finance-report-rows');rows.replaceChildren();const sold=vehicles.filter(v=>v.status==='sold');if(!sold.length)rows.append(node('p','','Tus cierres aparecerán aquí cuando registres la venta de un vehículo.'));for(const v of sold){const f=v.privateFinance||{},t=financeTotals(f),row=node('article','finance-report-row'),copy=node('div');copy.append(node('strong','',v.make+' '+v.name+' · '+v.year),node('p','',t.recorded?`${f.saleDate||'Sin fecha'} · Cierre: ${showAmount(t.sale,f.currency)} · Ganancia neta: ${showAmount(t.net,f.currency)} · Pendiente: ${showAmount(t.pending,f.currency)}`:'Vendido sin precio final registrado: todavía no suma a las ganancias.'));if(t.recorded&&f.advertisedAtSale?.currency===f.currency){const discount=f.advertisedAtSale.amount-t.sale;copy.append(node('small','',`Anunciado al cierre: ${showAmount(f.advertisedAtSale.amount,f.currency)} · ${discount>=0?'Rebaja negociada':'Sobre el precio anunciado'}: ${showAmount(Math.abs(discount),f.currency)}`));}const edit=node('button','','Revisar cierre');edit.type='button';edit.onclick=()=>openVehicle(v);row.append(copy,edit);rows.append(row);}}
 const exportButton=document.querySelector('#export-inventory');exportButton.textContent='Exportar inventario privado';exportButton.title='Incluye acuerdos y comisiones privados; no compartir como catálogo público.';
 return{capture,report:renderReport,setPrice(amount,currency){price.set(amount);form.elements.currency.value=currency;choices.forEach(c=>c.sync());draw();},open(vehicle){privateCurrencyTouched=!!vehicle?.privateFinance?.currency;const f=vehicle?.privateFinance||{};for(const [key,input]of Object.entries(fields)){const value=f[key]??(key==='currency'?(moneyParts(vehicle||{}).currency||'BOB'):key==='mode'?'percent':'');if(formats.has(key))formats.get(key).set(value);else input.value=value;}country.value='Bolivia';price.set(moneyParts(vehicle||{}).amount);for(const choice of choices)choice.sync();draw();},validate(){const f=capture();if(form.elements.status.value==='sold'&&f.salePrice!==null&&!f.saleDate)fields.saleDate.value=new Date().toLocaleDateString('en-CA',{timeZone:'America/La_Paz'});return capture();}};
}
